instantsearch.widgets.durtyFixPagination = function() {
    return {
        render: function render(options) {

            setTimeout(function() {
            var matches = document.querySelectorAll("#pagination a[href]");
            var urlBegin = window.location.protocol + '//' + window.location.hostname;
            var urlSearchBegin = urlBegin + '/?';
            angular.forEach(matches, function(a) {
            if (urlSearchBegin === a.href.substr(0, urlSearchBegin.length)) {
                a.href = urlBegin + window.location.pathname + a.href.substr(urlSearchBegin.length - 1);
            }
            });
            console.info('pagination fix done');
            }, 800);

        }
    };
};

search.addWidget(instantsearch.widgets.durtyFixPagination());
